function formatResponse(statusCode, body) {
  return {
    statusCode,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  };
}

function validateItem(input) {
  const errors = [];

  if (typeof input !== 'object' || input === null) {
    return { valid: false, errors: ['Request body must be a JSON object'] };
  }

  if (typeof input.name !== 'string' || input.name.trim().length === 0) {
    errors.push('"name" is required and must be a non-empty string');
  }

  if (input.description !== undefined && typeof input.description !== 'string') {
    errors.push('"description" must be a string when provided');
  }

  return { valid: errors.length === 0, errors };
}

function validatePartialItem(input) {
  const errors = [];

  if (typeof input !== 'object' || input === null) {
    return { valid: false, errors: ['Request body must be a JSON object'] };
  }

  if (input.name === undefined && input.description === undefined) {
    return { valid: false, errors: ['At least one of "name" or "description" must be provided'] };
  }

  if (input.name !== undefined && (typeof input.name !== 'string' || input.name.trim().length === 0)) {
    errors.push('"name" must be a non-empty string when provided');
  }

  if (input.description !== undefined && typeof input.description !== 'string') {
    errors.push('"description" must be a string when provided');
  }

  return { valid: errors.length === 0, errors };
}

const crypto = require('crypto');

function base64url(input) {
  return Buffer.from(input).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64urlDecode(input) {
  const padded = input.replace(/-/g, '+').replace(/_/g, '/');
  const padding = padded.length % 4 === 0 ? '' : '='.repeat(4 - (padded.length % 4));
  return Buffer.from(padded + padding, 'base64').toString();
}

function sign(headerAndPayload, secret) {
  return crypto.createHmac('sha256', secret).update(headerAndPayload).digest('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function generateJwt(payload, secret, expiresInSeconds) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const now = Math.floor(Date.now() / 1000);
  const fullPayload = { ...payload, iat: now, exp: now + expiresInSeconds };
  const encodedHeader = base64url(JSON.stringify(header));
  const encodedPayload = base64url(JSON.stringify(fullPayload));
  const signature = sign(`${encodedHeader}.${encodedPayload}`, secret);
  return `${encodedHeader}.${encodedPayload}.${signature}`;
}

function verifyJwt(token, secret) {
  const parts = typeof token === 'string' ? token.split('.') : [];
  if (parts.length !== 3) {
    return { valid: false, error: 'Malformed token' };
  }

  const [encodedHeader, encodedPayload, signature] = parts;
  const expectedSignature = sign(`${encodedHeader}.${encodedPayload}`, secret);

  const actualBuf = Buffer.from(signature);
  const expectedBuf = Buffer.from(expectedSignature);
  const signatureValid = actualBuf.length === expectedBuf.length
    && crypto.timingSafeEqual(actualBuf, expectedBuf);

  if (!signatureValid) {
    return { valid: false, error: 'Invalid signature' };
  }

  let payload;
  try {
    payload = JSON.parse(base64urlDecode(encodedPayload));
  } catch {
    return { valid: false, error: 'Malformed payload' };
  }

  if (payload.exp && Math.floor(Date.now() / 1000) > payload.exp) {
    return { valid: false, error: 'Token expired' };
  }

  return { valid: true, payload };
}

module.exports = {
  formatResponse,
  validateItem,
  validatePartialItem,
  generateJwt,
  verifyJwt,
};
